        attemptCount: { type: integer, minimum: 0 }
        startedAt: { $ref: "#/components/schemas/NullableTimestamp" }
        finishedAt: { $ref: "#/components/schemas/NullableTimestamp" }
        fileName: { type: [string, "null"] }
        contentType: { type: [string, "null"] }
        fileSha256: { type: [string, "null"], pattern: '^[0-9a-f]{64}$' }
        fileSizeBytes: { type: [integer, "null"], minimum: 1 }
        errorCode: { type: [string, "null"], enum: [export.render_failed, export.too_large, export.source_unavailable, export.retries_exhausted, null] }
        cancelledAt: { $ref: "#/components/schemas/NullableTimestamp" }
        version: { $ref: "#/components/schemas/Version" }
        createdAt: { $ref: "#/components/schemas/Timestamp" }
