  db: Db,
  boss: PgBoss,
  batchSize: number = OUTBOX_RELAY.batchSize,
): Promise<RelayResult> {
  let published = 0;
  let failed = 0;
  for (let i = 0; i < batchSize; i++) {
    const r = await publishNext(db, boss);
    if (r === "empty") break;
    if (r === "published") {
